-- Inspection and Acceptance Report (IAR) Module: 2 tables.
--   fims.iar_module            one row per PO: po_number, auto-generated iar_number (IAR-YYYY-0001, ...),
--                              Sales Invoice # and date.
--   fims.po_delivery_receipt   one row per delivered line; every line carries the iar_number of its PO,
--                              rows sharing dr_number belong to the same delivery receipt.
-- po_number and dr_number are free text typed by the user (no FK to the PO module yet — there are no POs).
-- Replaces the earlier IAR design. If you created the old IAR tables, drop them with:
--   DROP TABLE IF EXISTS fims.iar_items CASCADE;
--   DROP TABLE IF EXISTS fims.iar CASCADE;
--   DROP TABLE IF EXISTS fims.air_module_iar_items CASCADE;   -- (older names, if they exist)
--   DROP TABLE IF EXISTS fims.air_module_iar CASCADE;
--   DROP TABLE IF EXISTS fims.air_module_po CASCADE;
-- If you already created an earlier version of these tables locally, drop it first so this script recreates them:
--   DROP TABLE IF EXISTS fims.po_delivery_receipt CASCADE;
--   DROP TABLE IF EXISTS fims.iar_module CASCADE;

CREATE TABLE IF NOT EXISTS fims.iar_module (
    iar_id      SERIAL PRIMARY KEY,
    iar_number  VARCHAR(50)  NOT NULL,                  -- auto-generated by the app: IAR-YYYY-0001
    po_number   VARCHAR(100) NOT NULL,
    si_number   VARCHAR(100),                           -- Sales Invoice # (optional)
    si_date     DATE,                                   -- Sales Invoice date (optional)
    created_by  INTEGER,
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by  INTEGER,
    updated_at  TIMESTAMPTZ,
    CONSTRAINT uq_iar_module_iar_number UNIQUE (iar_number),
    CONSTRAINT uq_iar_module_po_number  UNIQUE (po_number)
);
COMMENT ON TABLE  fims.iar_module IS 'IAR header per PO number: IAR number + Sales Invoice details';
COMMENT ON COLUMN fims.iar_module.iar_number IS 'Auto-generated IAR number (IAR-YYYY-0001); copied to every delivery receipt line of the PO';

CREATE TABLE IF NOT EXISTS fims.po_delivery_receipt (
    dr_line_id     SERIAL PRIMARY KEY,
    po_number      VARCHAR(100)  NOT NULL,              -- FK -> fims.iar_module.po_number (ON DELETE CASCADE)
    iar_number     VARCHAR(50)   NOT NULL,              -- the PO's IAR number, copied from fims.iar_module
    dr_number      VARCHAR(100)  NOT NULL,              -- Delivery Receipt no.
    delivery_date  DATE          NOT NULL,
    account_code   VARCHAR(30),                         -- Property & Equipment account code only, e.g. 1-06-05-020 (required in the app when amount >= 50,000)
    description    TEXT          NOT NULL,
    quantity       INTEGER       NOT NULL DEFAULT 1,
    unit           VARCHAR(50)   NOT NULL,
    unit_price     NUMERIC(14,2) NOT NULL DEFAULT 0,
    amount         NUMERIC(14,2) NOT NULL DEFAULT 0,    -- quantity x unit_price, computed by the app
    model_no       VARCHAR(100),                        -- optional
    serial_no      VARCHAR(100),                        -- optional; unique when given (NULLs don't clash)
    property_no    VARCHAR(100),                        -- optional
    par_no         VARCHAR(100),                        -- optional
    created_by     INTEGER,
    created_at     TIMESTAMPTZ   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by     INTEGER,
    updated_at     TIMESTAMPTZ,
    CONSTRAINT uq_po_delivery_receipt_serial UNIQUE (serial_no),
    -- the PO of the IAR module: removing it from fims.iar_module automatically deletes its receipts
    CONSTRAINT fk_po_delivery_receipt_po FOREIGN KEY (po_number)
        REFERENCES fims.iar_module (po_number) ON UPDATE CASCADE ON DELETE CASCADE
);
COMMENT ON TABLE  fims.po_delivery_receipt IS 'Delivery Receipt lines per PO; each line carries its PO''s IAR number';
COMMENT ON COLUMN fims.po_delivery_receipt.dr_number IS 'Delivery Receipt number; lines with the same value belong to the same DR';
COMMENT ON COLUMN fims.po_delivery_receipt.amount IS 'quantity x unit_price, computed by the app';
COMMENT ON COLUMN fims.po_delivery_receipt.par_no IS 'Optional Property Acknowledgement Receipt (PAR) number';

CREATE INDEX IF NOT EXISTS idx_po_dr_iar_number ON fims.po_delivery_receipt (iar_number);
CREATE INDEX IF NOT EXISTS idx_po_dr_po_number ON fims.po_delivery_receipt (po_number);
CREATE INDEX IF NOT EXISTS idx_po_dr_dr_number ON fims.po_delivery_receipt (dr_number);
CREATE INDEX IF NOT EXISTS idx_po_dr_property  ON fims.po_delivery_receipt (property_no);
CREATE INDEX IF NOT EXISTS idx_po_dr_par       ON fims.po_delivery_receipt (par_no);
